@media (min-width: 1500px) { main { padding-top: 40px; } .cpu-chart-wrap { height: 340px; } .metric-card { padding: 20px 23px 17px; } .metric-label { font-size: 12px; } .metric-bottom { font-size: 10px; } .metric-tag { font-size: 9px; } }
