@media (max-width: 900px) { .sidebar { width: 72px; padding: 27px 10px 15px; align-items: center; } .brand { padding: 0; font-size: 0; gap: 0; } .brand-mark { margin: 0; } .brand-period { display: none; } .workspace { display: none; } .nav-caption { display: none; } .sidebar nav { margin-top: 42px; width: 100%; } .nav-item { padding: 14px; justify-content: center; } .nav-item span, .nav-item small { display: none; } .sidebar-bottom { padding: 0; } .system-status { display: none; } .profile { border: 0; padding: 0; } .profile div, .profile-dot { display: none; } .main-shell { margin-left: 72px; } .metric-label { font-size: 9px; } .metric-label svg { display: none; } .metric-tag { font-size: 7px; } .sparkline { width: 45px; min-width: 25px; } .bottom-grid { grid-template-columns: 1fr; } .collection-panel { padding-bottom: 20px; } .collection-panel dl { display: flex; justify-content: space-between; gap: 24px; } .collection-panel dl>div { flex: 1; display: block; margin: 0; } .collection-panel dd { margin-top: 5px; } }
@media (max-width: 640px) { .sidebar { display: none; } .main-shell { margin-left: 0; } .topbar { padding: 0 18px; height: 59px; } .topbar-actions { gap: 10px; } .breadcrumbs { gap: 7px; font-size: 9px; } .demo-badge { font-size: 8px; } .top-avatar, .topbar-divider { display: none; } main { padding: 24px 16px 0; } h1 { font-size: 28px; } .eyebrow { font-size: 7px; } .page-heading { align-items: flex-start; margin-bottom: 24px; } .page-heading p { font-size: 10px; max-width: 230px; } .export-button { font-size: 0; padding: 8px; margin-top: 20px; gap: 0; } .filter-bar { gap: 7px; } .host-filter { gap: 7px; } .filter-label { display: none; } select { width: 175px; font-size: 10px; } .healthy { font-size: 8px; } .metric-grid { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 10px; margin-bottom: 17px; } .metric-card { padding: 14px 15px 9px; } .metric-label { font-size: 9px; } .metric-label svg { display: block; } .metric-value { margin-top: 10px; font-size: 28px; } .metric-tag { font-size: 7px; } .sparkline { width: 62px; } .metric-bottom { font-size: 8px; } .chart-header { padding: 17px 15px 0; align-items: flex-start; gap: 8px; } .chart-header h2 { font-size: 12px; } .chart-header p { font-size: 8px; max-width: 145px; margin-top: 7px; } .live-badge { font-size: 6px; gap: 3px; } .chart-title-line { gap: 5px; } .chart-controls { gap: 5px; } .period-control { padding: 2px; } .period-control button { padding: 5px 8px; font-size: 8px; } .pause-button { width: 28px; height: 28px; } .chart-meta { padding: 18px 15px 0; } .chart-date { font-size: 7px; gap: 4px; } .legend-toggle, .legend-toggle strong { font-size: 9px; } .cpu-chart-wrap { height: 265px; margin: 5px 9px 0 3px; } .chart-footer { padding: 2px 15px 11px; gap: 8px; flex-wrap: wrap; } .chart-footer>span, .text-button { font-size: 8px; } .desktop-hint { display: none; } .chart-status { padding: 9px 15px; flex-wrap: wrap; gap: 6px; font-size: 8px; } .chart-status>span { gap: 4px; } .bottom-grid { margin-top: 17px; } .panel-heading { padding: 17px 16px; } th:first-child, td:first-child { padding-left: 16px; } td { padding: 10px; } .server-name strong { font-size: 9px; } .table-status { font-size: 8px; } .server-name { gap: 6px; } .server-name svg { width: 14px; } .collection-panel dl { gap: 12px; } .collection-panel dt { font-size: 9px; } .collection-panel dd { font-size: 8px; } .page-footer { font-size: 7px; gap: 10px; } .page-footer>span:last-child { display: none; } }
