.app { --bg: #f7f9f8; --surface: #fff; --text: #243b35; --muted: #87938f; --secondary: #687b73; --border: #e7ece9; --soft: #f5f8f6; --accent: #249d7f; --accent-soft: #eaf6ef; min-height: 100vh; background: var(--bg); color: var(--text); font-size: 13px; line-height: 1.5; }
.app.theme-dark { --bg: #111b18; --surface: #1a2621; --text: #e4eee8; --muted: #8c9d94; --secondary: #afbeb5; --border: #2a3a31; --soft: #202f27; --accent: #5dceb0; --accent-soft: #203d30; }
.sidebar { width: 224px; position: fixed; inset: 0 auto 0 0; background: #142d25; color: #adbbb4; display: flex; flex-direction: column; padding: 33px 18px 16px; z-index: 10; }
.brand { display: flex; align-items: center; color: #f6fff9; gap: 9px; font-size: 32px; font-weight: 700; letter-spacing: -1.4px; padding: 0 13px; width: fit-content; line-height: 1; }
.brand-mark { width: 32px; height: 32px; display: grid; place-items: center; background: #b6ecd1; color: #173c2c; border-radius: 10px; margin-right: 1px; }
.brand-period { color: #9cdbb9; margin-left: -8px; }
.workspace { display: flex; gap: 9px; align-items: center; margin: 34px 0 32px; border: 1px solid #335044; border-radius: 7px; padding: 11px 9px; }
