          <button className=\"button export-button\" onClick={exportCsv} aria-label={exported ? 'CSV сохранён' : 'Экспорт данных'}><Icon name={exported ? 'check' : 'download'} size={17}/>{exported ? 'CSV сохранён' : 'Экспорт данных'}</button>
        </section>

        <div className=\"filter-bar\"><div className=\"host-filter\"><span className=\"filter-label\">Сервер</span><div className=\"select-wrap\"><Icon name=\"server\" size={17}/><select aria-label=\"Выбрать сервер\" value={hostId} onChange={(event) => selectHost(event.target.value)}>{hosts.map((item) => <option key={item.id} value={item.id}>{item.id}</option>)}</select><Icon name=\"down\" size={14}/></div><span className=\"region\"><Icon name=\"globe\" size={14}/>{host.region}</span></div>
