test('"'releases observers, frames, tooltips, and timers when unmounted in StrictMode', async ({page}) => {
  const result = await page.evaluate(async () => {
    const w = window as any;
    // Dynamic imports use Vite's browser modules; this mounts a second isolated
    // application to exercise the real canvas lifecycle, including StrictMode.
    const React = (await import('/node_modules/.vite/deps/react.js' as string)).default;
    const {createRoot} = await import('/node_modules/.vite/deps/react-dom_client.js' as string);
    const {App} = await import('/src/App.tsx' as string);
    const observers = new Set<ResizeObserver>();
    const NativeObserver = window.ResizeObserver;
    window.ResizeObserver = class extends NativeObserver {
      constructor(cb: ResizeObserverCallback) {super(cb); observers.add(this);}
      disconnect() {observers.delete(this); super.disconnect();}
    };
    const timers = new Set<number>();
    const nativeInterval = window.setInterval.bind(window);
    const nativeClear = window.clearInterval.bind(window);
    window.setInterval = ((...args: Parameters<typeof window.setInterval>) => {
      const id = nativeInterval(...args); timers.add(id); return id;
    }) as typeof window.setInterval;
    window.clearInterval = (id) => {timers.delete(id"'!); nativeClear(id);};
    const host = document.createElement('"'div');
    document.body.append(host);
    const root = createRoot(host);
    root.render(React.createElement(React.StrictMode, null, React.createElement(App)));
    await new Promise((resolve) => setTimeout(resolve, 200));
    const mounted = {canvases: host.querySelectorAll('canvas').length, timers: timers.size, observers: observers.size};
    root.unmount();
    host.remove();
    await new Promise((resolve) => requestAnimationFrame(() => resolve(null)));
    window.ResizeObserver = NativeObserver;
    window.setInterval = nativeInterval;
    window.clearInterval = nativeClear;
    return {mounted, remaining: {timers: timers.size, observers: observers.size},
      canvases: document.querySelectorAll('.cpu-chart canvas').length,
      tooltips: document.querySelectorAll('.yagr-tooltip').length};
  });
  expect(result.mounted.canvases).toBe(1);
  expect(result.mounted.timers).toBe(1);
  expect(result.mounted.observers).toBeGreaterThan(0);
  expect(result.remaining).toEqual({timers: 0, observers: 0});
  expect(result.canvases).toBe(1);
  expect(result.tooltips).toBeLessThanOrEqual(1);
});
