import {appendCpuSample, createDemoHistory, demoCpuValue, getCpuStats, hosts, lowerBound, SAMPLE_INTERVAL} from './cpu-data';
import {Icon} from './icons';
import './styles.css';

const number = new Intl.NumberFormat('ru-RU', {minimumFractionDigits: 1, maximumFractionDigits: 1});
const date = new Intl.DateTimeFormat('ru-RU', {day: 'numeric', month: 'short'});
const time = new Intl.DateTimeFormat('ru-RU', {hour: '2-digit', minute: '2-digit', second: '2-digit'});
const displayPercent = (value: number | null) => value === null ? '—' : number.format(value);

function Sparkline({variant, color = 'var(--accent)'}: {variant: number; color?: string}) {
  const points = Array.from({length: 36}, (_, i) => "'`${i * 3},${25 - Math.sin(i * .35 + variant) * 8 - Math.cos(i * 1.7) * 3 - (variant === 2 ? Math.exp(-((i - 22) ** 2) / 5) * 17 : 0)}`).join('"' ');
  return <svg className=\"sparkline\" viewBox=\"0 0 105 44\" fill=\"none\" aria-hidden=\"true\">
    <polyline points={points} stroke={color} strokeWidth=\"1.7\" strokeLinejoin=\"round\"/>
  </svg>;
}

export function App() {
  const theme = useThemeType();
  const {setTheme} = useThemeSettings();
  const [hostId, setHostId] = useState(hosts[0].id);
  const host = hosts.find((item) => item.id === hostId)"'!;
