            <div className="chart-controls"><div className="period-control" role="group" aria-label="Период графика">{[1, 6, 24].map((value) => <button key={value} aria-pressed={hours === value} onClick={() => setHours(value)} className={hours === value ? '"'selected' : ''}>{value} ч</button>)}</div><button className={"'`pause-button ${paused ? '"'is-paused' : ''}"'`} onClick={() => setPaused((value) => !value)} aria-label={paused ? '"'Продолжить обновление' : 'Приостановить обновление'} aria-pressed={paused} title={paused ? 'Продолжить обновление' : 'Приостановить обновление'}><Icon name={paused ? 'play' : 'pause'} size={16}/></button></div>
          </div>
          <div className=\"chart-meta\"><label className=\"legend-toggle\"><input type=\"checkbox\" aria-label=\"Показать загрузку CPU\" checked={visible} onChange={(event) => setVisible(event.target.checked)}/><span className={"'`legend-line ${visible ? '"'' : 'hidden'}"'`}/><span>CPU</span><strong>{displayPercent(stats.current)}%</strong></label><span className="chart-date">{date.format(latestTime - hours * 3_600_000)} — {date.format(latestTime)}<span>·</span>{Intl.DateTimeFormat().resolvedOptions().timeZone}</span></div>
          <CpuChart history={history} hours={hours} resetKey={resetKey} visible={visible} onZoomChange={setZoomed}/>
          <div className="chart-footer"><span><Icon name="info" size={14}/><span className="desktop-hint">Выделите участок для увеличения. </span>Двойной клик — сброс масштаба.</span><button className="text-button" disabled={!zoomed} onClick={() => setResetKey((key) => key + 1)}><Icon name="reset" size={13}/>Сбросить масштаб</button></div>
          <div className="chart-status"><span><span className={`status-dot ${paused ? '"'gray' : ''}"'`}/>{paused ? '"'Обновление приостановлено' : 'Обновляется каждые 2 секунды'}</span><span>{stats.count.toLocaleString('ru-RU')} точек<span className=\"status-separator\">/</span>Обновлено в {time.format(latestTime)}</span></div>
        </section>

        <div className=\"bottom-grid\">
          <section id=\"servers\" className=\"panel servers-panel\"><div className=\"panel-heading\"><h2>Серверы</h2><span className=\"count-badge\">3</span><span className=\"panel-note\">Демо-инфраструктура</span></div>
            <div className=\"table-scroll\"><table><thead><tr><th>Имя сервера</th><th>Статус</th><th>CPU</th><th aria-label=\"Выбор сервера\"/></tr></thead><tbody>{hosts.map((item) => <tr key={item.id} className={item.id === hostId ? 'selected-row' : ''}><td><span className=\"server-name\"><Icon name=\"server\" size={17}/><span><strong>{item.id}</strong><small>{item.ip}</small></span></span></td><td><span className=\"table-status\"><span className=\"status-dot\"/>Доступен</span></td><td><span className=\"cpu-cell\">{displayPercent(demoCpuValue(latestTime, item.offset))}%<span className=\"mini-bar\"><span style={{width: "'`${demoCpuValue(latestTime, item.offset)}%`}}/></span></span></td><td><button className="icon-button" aria-label={`Показать метрики ${item.id}`} title={`Показать ${item.id}`} onClick={() => {selectHost(item.id); document.getElementById('"'cpu')?.scrollIntoView({behavior: 'smooth', block: 'center'});}}><Icon name=\"chevron\" size={16}/></button></td></tr>)}</tbody></table></div>
          </section>
          <section id=\"details\" className=\"panel collection-panel\"><div className=\"panel-heading\"><span className=\"collection-icon\"><Icon name=\"pulse\" size={18}/></span><h2>О сборе метрик</h2></div><p>Полная картина без пропущенных деталей.</p><dl><div><dt>Интервал сбора</dt><dd>2 секунды</dd></div><div><dt>Глубина истории</dt><dd>24 часа</dd></div><div><dt>Источник данных</dt><dd><span className=\"status-dot\"/>Демопоток</dd></div></dl><div className=\"collection-info\"><Icon name=\"info\" size={15}/><span>Демонстрационные данные. Реальные серверы не подключены.</span></div></section>
        </div>
        <footer className=\"page-footer\"><span><span className=\"footer-brand\">pulse.</span> Спокойствие в каждой метрике.</span><span><span className=\"status-dot\"/>Все 3 сервера доступны</span></footer>
        <div className=\"sr-only\" role=\"status\">{exported ? 'Данные графика экспортированы в CSV' : ''}</div>
      </main>
    </div>
  </div>;
}
